/// <summary>
/// CB167_PerformStockReservation
/// This is a data contract class for reserve event orders batch job.
/// </summary>
[
    DataContract
    , SysOperationContractProcessing(classStr(METSalesOrderGuideCheckUIBuilder))
]
class METSalesOrderGuideCheckContract extends METSysOperationTaskDataContract
{
    SalesId salesId;
    guid    topPickingProcessId;

}

Method.Source:
/// <summary>
/// Gets and sets sales Id.
/// </summary>
/// <param name = "_salesId">Sales Id.</param>
/// <returns>Sales Id.</returns>
[DataMember]
public SalesId parmSalesId(SalesId _salesId = salesId)
{
    salesId = _salesId;
    return salesId;
}

/// <summary>
/// get/set the top picking process guid id
/// </summary>
/// <param name = "_topPickingProcessId">Top picking process guid id</param>
/// <returns>Top picking process guid id</returns>
[DataMember, SysOperationControlVisibility(false)]
public guid parmTopPickingProcessId(guid _topPickingProcessId = topPickingProcessId)
{
    topPickingProcessId = _topPickingProcessId;
    return topPickingProcessId;
}
